#pragma once
#include "new_controller/harmonic_worker.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
namespace ego4p0 {
// A topology-only coarse layer has no numerical residual or potential.
// JSON must represent unavailable numbers as null, never bare nan/inf.
struct HarmonicJsonNumber { double value; };
inline std::ostream &operator<<(std::ostream &out,HarmonicJsonNumber number) {
  if(std::isfinite(number.value))out<<number.value;else out<<"null";
  return out;
}
inline void save_harmonic(const std::filesystem::path &dir,const HarmonicResult &r) {
  for(const auto &entry:{std::pair<const char*,const FieldLayer*>{"coarse",&r.coarse},{"fine",&r.fine}}) {
    std::ofstream f(dir/(std::string(entry.first)+"_field.csv"));
    f<<std::setprecision(17)<<"cell,alpha_deg,beta_deg,state,boundary,phi,cameras,adaptive_owner\n";const auto &l=*entry.second;
    for(uint32_t id=0;id<l.layout.cells();++id)f<<id<<','<<-180+(id%l.layout.azimuth_bins+.5)*l.layout.azimuth_deg<<','<<-90+(id/l.layout.azimuth_bins+.5)*l.layout.elevation_deg<<','<<unsigned(l.state[id])<<','<<unsigned(l.boundary[id])<<','<<l.phi[id]<<','<<unsigned(l.cameras[id])<<','<<(entry.second==&r.fine&&r.adaptive.nodes?r.adaptive.owner[id]:UINT32_MAX)<<'\n';
    if(!f)throw std::runtime_error("cannot export harmonic field");
  }
  std::ofstream summaries(dir/"coarse_image.csv");summaries<<std::setprecision(17)<<"camera,block,mean_z,min_rho,raw_min_rho,valid_pixels,raw_valid_pixels,total_pixels\n";
  for(uint32_t camera=0;camera<4;++camera)for(uint32_t i=0;i<r.coarse_image[camera].size();++i){const auto &s=r.coarse_image[camera][i];summaries<<camera<<','<<i<<','<<s.mean_z<<','<<s.min_rho<<','<<s.raw_min_rho<<','<<s.valid<<','<<s.raw_valid<<','<<s.total<<'\n';}
  if(!summaries)throw std::runtime_error("cannot export second image summary");
  std::ofstream c(dir/"reference_curve.csv");c<<std::setprecision(17)<<"step,tau,alpha_deg,beta_deg,x,y,z,F_alpha,F_beta,gx,gy,gz,norm2,cell,valid,local_chart,zeta_rad,potential,magnitude,unit_alpha,unit_beta,unit_x,unit_y,unit_z,zero_field\n";
  for(uint32_t k=0;k<r.curve_size;++k) {const auto &p=r.curve[k];c<<k<<','<<p.tau<<','<<p.alpha*180/direction_pi<<','<<p.beta*180/direction_pi;for(double x:p.direction)c<<','<<x;c<<','<<p.F_alpha<<','<<p.F_beta;for(double x:p.gradient_B)c<<','<<x;c<<','<<p.norm2<<','<<p.cell<<','<<p.valid<<','<<p.local_chart<<','<<p.zeta<<','<<p.potential<<','<<p.magnitude<<','<<p.unit_alpha<<','<<p.unit_beta;for(double x:p.unit_B)c<<','<<x;c<<','<<p.zero_field<<'\n';}
  std::ofstream an(dir/"adaptive_nodes.csv"),ae(dir/"adaptive_faces.csv");an<<std::setprecision(17)<<"node,representative,refined,boundary,phi\n";ae<<std::setprecision(17)<<"from,to,conductance\n";
  for(uint32_t i=0;i<r.adaptive.nodes;++i){an<<i<<','<<r.adaptive.representative[i]<<','<<unsigned(r.adaptive.refined[i])<<','<<unsigned(r.adaptive.boundary[i])<<','<<r.adaptive.phi[i]<<'\n';for(uint32_t e=r.adaptive.offset[i];e<r.adaptive.offset[i+1];++e)ae<<i<<','<<r.adaptive.neighbor[e]<<','<<r.adaptive.weight[e]<<'\n';}
  if(!an||!ae)throw std::runtime_error("cannot export adaptive graph");
  std::ofstream m(dir/"harmonic_meta.json");m<<std::setprecision(17)<<"{\"status\":\""<<field_status_name(r.status)<<"\",\"termination\":\""<<curve_end_name(r.termination)<<"\",\"version\":"<<r.version<<",\"sequence\":"<<r.sequence<<",\"stamp_ns\":"<<r.stamp_ns<<",\"configuration\":"<<r.configuration<<",\"geometry\":"<<r.geometry<<",\"parameter_revision\":"<<r.parameter_revision<<",\"fine_boundary_mode\":\""<<(r.fine_neumann_roi?"local_corridor_neumann":"coarse_dirichlet_coupling")<<"\",\"fine_corridor_deg\":"<<r.fine_corridor_deg<<",\"curve_max_step_deg\":"<<r.curve_max_step_deg<<",\"coarse_status\":\""<<field_status_name(r.coarse.status)<<"\",\"fine_status\":\""<<field_status_name(r.fine.status)<<"\",\"coarse_residual\":"<<HarmonicJsonNumber{r.coarse.residual}<<",\"fine_residual\":"<<HarmonicJsonNumber{r.fine.residual}<<",\"coarse_iterations\":"<<r.coarse.iterations<<",\"fine_iterations\":"<<r.fine.iterations<<",\"coarse_nodes\":"<<r.coarse.nodes<<",\"fine_nodes\":"<<r.fine.nodes<<",\"total_ms\":"<<r.total_ns/1e6<<",\"capture_ms\":"<<r.capture_ns/1e6<<",\"coarse_solve_ms\":"<<r.coarse.solve_ns/1e6<<",\"fine_solve_ms\":"<<r.fine.solve_ns/1e6<<",\"curve_ms\":"<<r.curve_ns/1e6<<",\"fine_attempts\":"<<r.fine_attempts<<",\"integration_steps\":"<<r.integration_steps<<",\"gradient_queries\":"<<r.gradient_queries<<",\"coarse_mixed\":"<<r.coarse_mixed<<",\"expanded\":"<<r.expanded<<",\"exit_clipped\":"<<r.exit_clipped<<",\"reused\":"<<r.reused<<",\"adaptive_nodes\":"<<r.adaptive.nodes<<",\"refined_nodes\":"<<r.adaptive.refined_nodes<<",\"angular_length_rad\":"<<r.angular_length<<",\"anchor_potential\":"<<r.anchor_potential<<",\"field_ms\":"<<r.field_ns/1e6<<",\"query_ms\":"<<r.query_ns/1e6<<",\"segment_ms\":"<<r.segment_ns/1e6<<",\"field_version\":"<<r.field_version<<",\"curve_version\":"<<r.curve_version<<",\"exit_direction\":["<<r.exit_direction[0]<<','<<r.exit_direction[1]<<','<<r.exit_direction[2]<<"],\"coarse_graph_reused\":"<<r.coarse_graph_reused<<",\"coarse_graph_cache_ms\":"<<r.coarse_graph_cache_ns/1e6<<",\"coarse_topology_only\":"<<r.coarse_topology_only<<",\"coarse_topology_ms\":"<<r.coarse_topology_ns/1e6<<",\"coarse_topology_failure\":\""<<r.coarse_topology_failure<<"\",\"coarse_solve_cpu_ms\":"<<r.coarse.solve_cpu_ns/1e6<<",\"fine_solve_cpu_ms\":"<<r.fine.solve_cpu_ns/1e6<<",\"coarse_interpolation\":\""<<(r.fine_neumann_roi?"none_local_neumann":"constant_FV_prolongation")<<"\",\"curve_parameter\":\"angular_arc_length_rad\",\"image_first_block_edge\":"<<r.image_first_block_edge<<",\"image_second_block_edge\":"<<r.image_second_block_edge<<",\"image_columns\":"<<r.image_columns<<",\"image_rows\":"<<r.image_rows<<",\"motion_publishers_created\":0}\n";
  if(!m||!c)throw std::runtime_error("cannot export harmonic metadata/curve");
}
inline void save_harmonic_events(const std::filesystem::path &dir,const HarmonicWorker &worker) {
  std::ofstream f(dir/"harmonic_jobs.csv");f<<std::setprecision(12)<<"version,sequence,stamp_ns,completed_ns,total_ms,capture_ms,coarse_solve_ms,fine_solve_ms,curve_ms,coarse_residual,fine_residual,coarse_iterations,fine_iterations,coarse_nodes,fine_nodes,curve_steps,status,termination,expanded,reused,potential_version,curve_version,component_ms,coarse_domain_ms,fine_domain_ms,coarse_cache_ms,coarse_assembly_ms,coarse_iteration_ms,coarse_residual_ms,coarse_store_ms,fine_cache_ms,fine_assembly_ms,fine_iteration_ms,fine_residual_ms,fine_store_ms,query_ms,segment_ms,refined_nodes,angular_length_rad,coarse_status,coarse_topology_ms,coarse_solve_cpu_ms,fine_solve_cpu_ms,coarse_graph_reused,coarse_graph_cache_ms\n";
  for(const auto &e:worker.events())f<<e.version<<','<<e.sequence<<','<<e.stamp_ns<<','<<e.completed_ns<<','<<e.total_ns/1e6<<','<<e.capture_ns/1e6<<','<<e.coarse_ns/1e6<<','<<e.fine_ns/1e6<<','<<e.curve_ns/1e6<<','<<e.coarse_residual<<','<<e.fine_residual<<','<<e.coarse_iterations<<','<<e.fine_iterations<<','<<e.coarse_nodes<<','<<e.fine_nodes<<','<<e.curve_steps<<','<<field_status_name(e.status)<<','<<curve_end_name(e.termination)<<','<<e.expanded<<','<<e.reused<<','<<e.potential_version<<','<<e.curve_version<<','<<e.component_ns/1e6<<','<<e.coarse_domain_ns/1e6<<','<<e.fine_domain_ns/1e6<<','<<e.coarse_cache_ns/1e6<<','<<e.coarse_assembly_ns/1e6<<','<<e.coarse_iteration_ns/1e6<<','<<e.coarse_residual_ns/1e6<<','<<e.coarse_store_ns/1e6<<','<<e.fine_cache_ns/1e6<<','<<e.fine_assembly_ns/1e6<<','<<e.fine_iteration_ns/1e6<<','<<e.fine_residual_ns/1e6<<','<<e.fine_store_ns/1e6<<','<<e.query_ns/1e6<<','<<e.segment_ns/1e6<<','<<e.refined_nodes<<','<<e.angular_length<<','<<field_status_name(e.coarse_status)<<','<<e.coarse_topology_ns/1e6<<','<<e.coarse_cpu_ns/1e6<<','<<e.fine_cpu_ns/1e6<<','<<e.coarse_graph_reused<<','<<e.coarse_graph_cache_ns/1e6<<'\n';
  if(!f)throw std::runtime_error("cannot export harmonic jobs");
}
} // namespace ego4p0
